// A `StatusOr<T>` represents either a usable value of type `T`, or an error
// `Status` explaining why such a value is not present. Callers can inspect
// `ok()` (or `operator bool`) to decide which of the two the object holds.
//
//   StatusOr<int> result = MayFail();
//   if (!result.ok()) {
//     return result.status();
//   }
//   Use(*result);

#pragma once

#include <type_traits>
#include <utility>

#include "ray/common/status.h"
#include "ray/util/logging.h"

namespace ray {

template <typename T>
class StatusOr {
 public:
  using value_type = T;

  // Allow conversions between StatusOr of related types (e.g. Derived -> Base).
  template <typename U>
  friend class StatusOr;

  // Default constructor produces a `StatusOr` holding an unknown error, since a
  // default-constructed `StatusOr` does not hold a value.
  StatusOr() : status_(StatusCode::UnknownError, "Uninitialized StatusOr") {}

  // Implicitly construct from a `Status`. The status must not be OK, otherwise
  // there would be no value to hold.
  StatusOr(const Status &status) : status_(status) {  // NOLINT
    RAY_CHECK(!status_.ok())
        << "Constructing StatusOr with an OK status is not allowed.";
  }
  StatusOr(Status &&status) : status_(std::move(status)) {  // NOLINT
    RAY_CHECK(!status_.ok())
        << "Constructing StatusOr with an OK status is not allowed.";
  }

  // Implicitly construct from a value.
  StatusOr(const T &value) : status_(Status::OK()), value_(value) {}  // NOLINT
  StatusOr(T &&value)                                                 // NOLINT
      : status_(Status::OK()), value_(std::move(value)) {}

  StatusOr(const StatusOr &) = default;
  StatusOr &operator=(const StatusOr &) = default;
  StatusOr(StatusOr &&) = default;
  StatusOr &operator=(StatusOr &&) = default;

  // Allow implicit conversion from `StatusOr<U>` where `U` is convertible to
  // `T` (e.g. `StatusOr<Derived>` -> `StatusOr<Base>`).
  template <typename U,
            typename = std::enable_if_t<std::is_convertible_v<U, T> &&
                                        !std::is_same_v<U, T>>>
  StatusOr(const StatusOr<U> &other)  // NOLINT
      : status_(other.status_), value_(other.value_) {}

  template <typename U,
            typename = std::enable_if_t<std::is_convertible_v<U, T> &&
                                        !std::is_same_v<U, T>>>
  StatusOr(StatusOr<U> &&other)  // NOLINT
      : status_(std::move(other.status_)), value_(std::move(other.value_)) {}

  ~StatusOr() = default;

  // Returns true if this holds a value.
  bool ok() const { return status_.ok(); }
  explicit operator bool() const { return ok(); }

  // Returns the contained status.
  const Status &status() const & { return status_; }
  Status status() && { return std::move(status_); }

  // Returns the status code.
  StatusCode code() const { return status_.code(); }

  // Returns a reference to the contained value. Fatally fails if not ok.
  T &value() & {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status_.ToString();
    return value_;
  }
  const T &value() const & {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status_.ToString();
    return value_;
  }
  T &&value() && {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status_.ToString();
    return std::move(value_);
  }

  // Dereference operators. No status check is performed.
  const T &operator*() const & { return value_; }
  T &operator*() & { return value_; }
  T &&operator*() && { return std::move(value_); }

  const T *operator->() const { return &value_; }
  T *operator->() { return &value_; }

  // Returns the contained value if ok, otherwise `default_val`.
  template <typename U>
  T value_or(U &&default_val) const & {
    if (ok()) {
      return value_;
    }
    return static_cast<T>(std::forward<U>(default_val));
  }
  template <typename U>
  T value_or(U &&default_val) && {
    if (ok()) {
      return std::move(value_);
    }
    return static_cast<T>(std::forward<U>(default_val));
  }

  // Returns the contained value if ok, otherwise a default-constructed `T`.
  T value_or_default() const & {
    if (ok()) {
      return value_;
    }
    return T{};
  }
  T value_or_default() && {
    if (ok()) {
      return std::move(value_);
    }
    return T{};
  }

  // Applies `f` to the contained value if ok, otherwise propagates the error.
  template <typename F>
  auto and_then(F &&f) const & {
    using Result = std::invoke_result_t<F, const T &>;
    if (ok()) {
      return std::forward<F>(f)(value_);
    }
    return Result(status_);
  }
  template <typename F>
  auto and_then(F &&f) && {
    using Result = std::invoke_result_t<F, T &&>;
    if (ok()) {
      return std::forward<F>(f)(std::move(value_));
    }
    return Result(std::move(status_));
  }

  // Applies `f` to the contained status if not ok (to recover), otherwise
  // propagates the value.
  template <typename F>
  auto or_else(F &&f) const & {
    using Result = std::invoke_result_t<F, const Status &>;
    if (ok()) {
      return Result(value_);
    }
    return std::forward<F>(f)(status_);
  }
  template <typename F>
  auto or_else(F &&f) && {
    using Result = std::invoke_result_t<F, Status &&>;
    if (ok()) {
      return Result(std::move(value_));
    }
    return std::forward<F>(f)(std::move(status_));
  }

  // Swaps the contents with `other`.
  void swap(StatusOr &other) {
    using std::swap;
    swap(status_, other.status_);
    swap(value_, other.value_);
  }

 private:
  Status status_;
  T value_{};
};

template <typename T>
bool operator==(const StatusOr<T> &lhs, const StatusOr<T> &rhs) {
  if (lhs.ok() != rhs.ok()) {
    return false;
  }
  if (lhs.ok()) {
    return *lhs == *rhs;
  }
  return lhs.code() == rhs.code();
}

template <typename T>
bool operator!=(const StatusOr<T> &lhs, const StatusOr<T> &rhs) {
  return !(lhs == rhs);
}

template <typename T>
void swap(StatusOr<T> &lhs, StatusOr<T> &rhs) {
  lhs.swap(rhs);
}

}  // namespace ray
